{
  "database": {
    "tables": [
      {
        "name": "waitlist_signups",
        "purpose": "Records every shopper email against the specific variant (or product-level fallback) they want to be notified about when it returns to stock.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "shopper_email", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "email address submitted by the shopper; no customer account required" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "the specific variant the shopper is waiting on; for single-variant products this is the default variant id" },
          { "name": "product_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "the parent product; used for product-deletion cascade and dashboard grouping" },
          { "name": "product_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized at signup time so emails render correctly even if the product is later edited" },
          { "name": "variant_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized at signup time for the same reason as product_title" },
          { "name": "product_url", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "storefront URL denormalized at signup so the notification email can include a direct link" },
          { "name": "unsubscribe_token", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "unique token embedded in every email's one-click unsubscribe link" },
          { "name": "status", "sqlType": "TEXT", "constraints": "NOT NULL DEFAULT 'active'", "purpose": "active | notified | unsubscribed | purged", "enum": ["active", "notified", "unsubscribed", "purged"] },
          { "name": "signed_up_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": "FIFO queue ordering — earlier timestamps are notified first during partial restocks" },
          { "name": "deleted_at", "sqlType": "TIMESTAMPTZ", "constraints": "NULL", "purpose": "soft-delete timestamp set when the parent product is deleted" }
        ],
        "uniqueConstraint": ["shopper_email", "variant_external_id"],
        "indexes": [
          ["variant_external_id", "status", "signed_up_at"],
          ["product_external_id"],
          ["unsubscribe_token"]
        ],
        "foreignKeys": []
      },
      {
        "name": "variant_availability",
        "purpose": "Tracks the last-observed availability state of each variant so the system can detect true restock transitions and prevent duplicate notification runs when stock briefly dips.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "the variant whose availability is being observed" },
          { "name": "product_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "parent product for cascade deletes" },
          { "name": "availability_state", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "last observed state: out_of_stock | available", "enum": ["out_of_stock", "available"] },
          { "name": "last_out_of_stock_at", "sqlType": "TIMESTAMPTZ", "constraints": "NULL", "purpose": "timestamp of the most recent out-of-stock transition; used to gate notification run dedup — a run is only created if it was created after this timestamp" },
          { "name": "last_available_at", "sqlType": "TIMESTAMPTZ", "constraints": "NULL", "purpose": "timestamp of the most recent in-stock transition" }
        ],
        "uniqueConstraint": ["variant_external_id"],
        "indexes": [],
        "foreignKeys": []
      },
      {
        "name": "notification_runs",
        "purpose": "Represents one restock event for a variant — the batch of sends triggered when that variant came back in stock.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "the variant that triggered this run" },
          { "name": "product_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "parent product for dashboard grouping" },
          { "name": "product_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized from the in-stock event for historical display" },
          { "name": "variant_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized from the in-stock event for historical display" },
          { "name": "status", "sqlType": "TEXT", "constraints": "NOT NULL DEFAULT 'open'", "purpose": "open | completed | cancelled", "enum": ["open", "completed", "cancelled"] },
          { "name": "available_units", "sqlType": "INTEGER", "constraints": "NOT NULL", "purpose": "inventory quantity at the time the restock was detected; determines how many signups to select from the front of the queue" },
          { "name": "sends_enqueued", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "number of notification sends created for this run" },
          { "name": "sends_dispatched", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "pre-aggregated count of dispatched sends for the history dashboard" },
          { "name": "sends_failed", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "pre-aggregated count of failed sends for the history dashboard" },
          { "name": "conversions", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "pre-aggregated count of attributed purchases within 7 days for lost-demand-recovered metric" },
          { "name": "created_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": null }
        ],
        "uniqueConstraint": [],
        "indexes": [
          ["variant_external_id", "created_at"],
          ["product_external_id", "created_at"]
        ],
        "foreignKeys": []
      },
      {
        "name": "notification_sends",
        "purpose": "One row per individual email send attempt within a notification run; drives the delivery queue and attribution lookups.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "run_id", "sqlType": "UUID", "constraints": "NOT NULL REFERENCES notification_runs(id) ON DELETE CASCADE", "purpose": "the parent notification run" },
          { "name": "signup_id", "sqlType": "UUID", "constraints": "NOT NULL REFERENCES waitlist_signups(id) ON DELETE CASCADE", "purpose": "the waitlist signup being notified" },
          { "name": "shopper_email", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized for fast attribution queries without joining to signups" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "denormalized for fast attribution queries" },
          { "name": "status", "sqlType": "TEXT", "constraints": "NOT NULL DEFAULT 'enqueued'", "purpose": "enqueued | dispatched | failed | held_quiet_hours", "enum": ["enqueued", "dispatched", "failed", "held_quiet_hours"] },
          { "name": "enqueued_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": null },
          { "name": "dispatched_at", "sqlType": "TIMESTAMPTZ", "constraints": "NULL", "purpose": null },
          { "name": "failure_reason", "sqlType": "TEXT", "constraints": "NULL", "purpose": null },
          { "name": "converted", "sqlType": "BOOLEAN", "constraints": "NOT NULL DEFAULT false", "purpose": "true when a paid order attributed this send within the 7-day window" }
        ],
        "uniqueConstraint": ["run_id", "signup_id"],
        "indexes": [
          ["status", "enqueued_at"],
          ["shopper_email", "variant_external_id", "status"],
          ["run_id"]
        ],
        "foreignKeys": []
      },
      {
        "name": "conversion_events",
        "purpose": "Records each attributed purchase so the lost-demand-recovered metric is accurate and idempotent on duplicate order-paid webhooks.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "order_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "dedup key — one conversion event per paid order" },
          { "name": "send_id", "sqlType": "UUID", "constraints": "NOT NULL REFERENCES notification_sends(id) ON DELETE CASCADE", "purpose": "the notification send that is credited with this conversion" },
          { "name": "shopper_email", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": null },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": null },
          { "name": "converted_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": null }
        ],
        "uniqueConstraint": ["order_external_id", "send_id"],
        "indexes": [
          ["order_external_id"],
          ["variant_external_id"]
        ],
        "foreignKeys": []
      },
      {
        "name": "email_template",
        "purpose": "Stores the merchant's editable email subject and body template used for all back-in-stock notification emails.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "singleton row guard — code enforces at most one row" },
          { "name": "subject_template", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "handlebars-style template supporting {{product_name}}, {{variant_title}} variables" },
          { "name": "body_template", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "handlebars-style template supporting {{product_name}}, {{variant_title}}, {{product_url}}, {{unsubscribe_url}} variables" },
          { "name": "updated_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": null }
        ],
        "uniqueConstraint": [],
        "indexes": [],
        "foreignKeys": []
      },
      {
        "name": "app_settings",
        "purpose": "Stores merchant-configured operational settings: quiet-hours window and delivery batch size.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "singleton row guard — code enforces at most one row" },
          { "name": "quiet_hours_start", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 22", "purpose": "hour of day (0-23) at which quiet period begins; sends are held until quiet_hours_end" },
          { "name": "quiet_hours_end", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 8", "purpose": "hour of day (0-23) at which quiet period ends and held sends are released" },
          { "name": "batch_size", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 50", "purpose": "maximum number of emails to dispatch per schedule tick to avoid rate-limit spikes" },
          { "name": "updated_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": null }
        ],
        "uniqueConstraint": [],
        "indexes": [],
        "foreignKeys": []
      },
      {
        "name": "demand_snapshots",
        "purpose": "Pre-aggregated per-variant demand metrics refreshed on each notification run creation and each new signup, enabling instant-load admin dashboard without full-table scans.",
        "columns": [
          { "name": "id", "sqlType": "UUID", "constraints": "PRIMARY KEY DEFAULT gen_random_uuid()", "purpose": "internal id" },
          { "name": "variant_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "the variant these metrics describe" },
          { "name": "product_external_id", "sqlType": "BIGINT", "constraints": "NOT NULL", "purpose": "parent product for grouping by product on the dashboard" },
          { "name": "product_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized for dashboard display without a product lookup" },
          { "name": "variant_title", "sqlType": "TEXT", "constraints": "NOT NULL", "purpose": "denormalized for dashboard display" },
          { "name": "active_signup_count", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "number of signups with status=active; dashboard ranking key" },
          { "name": "total_notified", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "cumulative dispatched sends across all runs" },
          { "name": "total_converted", "sqlType": "INTEGER", "constraints": "NOT NULL DEFAULT 0", "purpose": "cumulative conversions attributed to notifications" },
          { "name": "last_restock_at", "sqlType": "TIMESTAMPTZ", "constraints": "NULL", "purpose": "timestamp of the most recent notification run for this variant" },
          { "name": "snapshot_updated_at", "sqlType": "TIMESTAMPTZ", "constraints": "NOT NULL DEFAULT now()", "purpose": "when this row was last recalculated; used to detect stale snapshots" }
        ],
        "uniqueConstraint": ["variant_external_id"],
        "indexes": [
          ["active_signup_count"]
        ],
        "foreignKeys": []
      }
    ]
  },
  "shopifyIntegration": {
    "webhookTopics": [
      "variants/in_stock",
      "variants/out_of_stock",
      "products/delete",
      "orders/paid"
    ],
    "cronSchedule": "*/5 * * * *"
  },
  "httpRoutes": {
    "widget": [
      {
        "path": "/widget/status",
        "method": "GET",
        "purpose": "Return whether the requested variant is out of stock and whether the given email is already signed up"
      },
      {
        "path": "/widget/signups",
        "method": "POST",
        "purpose": "Record a shopper's email on the waitlist for a specific variant; duplicate signups are silently ignored"
      },
      {
        "path": "/widget/unsubscribe",
        "method": "POST",
        "purpose": "Remove a shopper from all their active waitlists via the one-click unsubscribe token"
      }
    ],
    "admin": [
      {
        "path": "/admin/dashboard",
        "method": "GET",
        "purpose": "Return a paginated list of variants ranked by active signup count for the merchant demand dashboard"
      },
      {
        "path": "/admin/variants/subscribers",
        "method": "GET",
        "purpose": "Return a paginated list of individual subscribers for a specific variant"
      },
      {
        "path": "/admin/variants/subscribers/export",
        "method": "GET",
        "purpose": "Stream a properly-escaped CSV of all active subscribers for a given variant"
      },
      {
        "path": "/admin/runs",
        "method": "GET",
        "purpose": "Return a paginated history of notification runs"
      },
      {
        "path": "/admin/email-template",
        "method": "GET",
        "purpose": "Return the current email subject and body template"
      },
      {
        "path": "/admin/email-template",
        "method": "PUT",
        "purpose": "Persist updated email subject and body template text"
      },
      {
        "path": "/admin/settings",
        "method": "GET",
        "purpose": "Return current quiet-hours start/end times and batch size"
      },
      {
        "path": "/admin/settings",
        "method": "PUT",
        "purpose": "Persist updated quiet-hours window and delivery batch size"
      }
    ]
  }
}
